import math
def is_opposite_vertical(x1, y1, x2, y2):
	# Calculate the angle of the line between (x1, y1) and (x2, y2)
	angle_radians = math.atan2(y2 - y1, x2 - x1)

	# Calculate sine and cosine of the angle
	sin_theta = math.sin(angle_radians)
	cos_theta = math.cos(angle_radians)

	# Determine if the opposite side (vertical component) is larger
	if abs(sin_theta) > abs(cos_theta):
		return True
	else:
		return False


def dire(lat,lng, meX, meY, oX, oY):
	if lat in [0,1] and lng in [0,1]:
		if abs(meX-oX)>abs(meY-oY):
			return 'vert'
		else:
			return 'horz'

	if lat==0 or lat==1:
		return 'horz'
	elif lng==0 or lng==1:
		return 'vert'		

def deployArrow(x, y, direction, latlng, seg):
	if latlng=='horz':
		if direction==1:
			cx=x+11
			cy=y
		else:
			cx=x-11
			cy=y
	else:
		if direction==1:
			cy=y+11
			cx=x
		else:
			cy=y-11
			cx=x	
	points='{},{} {},{} {},{} {},{}'.format(-7+cx,0+cy, 7+cx,-7+cy, 7+cx,7+cy, -7+cx,0+cy)
	return [points,[cx,cy]]

def arrowRotation(exit, uuid, cuuid, lat, lng):
	if exit =='vert':
		if cuuid==uuid:
			if lng>0.5:
				return 90
			else:
				return 270
		else:
			if lng<0.5:
				return 90
			else:
				return 270
	elif exit =='horz':
		if cuuid==uuid:
			if lat>0.5:
				return 180
			else:
				return 0
		else:
			if lat<0.5:
				return 180
			else:
				return 0
def rotate_point(x, y, x0, y0, theta):
	# Calculate new x and y based on rotation matrix
	x_new = x0 + (x - x0) * math.cos(theta) - (y - y0) * math.sin(theta)
	y_new = y0 + (x - x0) * math.sin(theta) + (y - y0) * math.cos(theta)
	return [x_new, y_new]

def distance_between_points(x1, y1, x2, y2):
	return math.sqrt((x2 - x1)**2 + (y2 - y1)**2)

